#!/usr/bin/env bash
# Son Hábitos: is the plan builder API alive? Usage: bash check.sh   (generated by agent/packs.mjs)
set -u
BASE="https://son-habitos.vercel.app"
for u in "$BASE/api/openapi" "$BASE/api/questions?lang=es" "$BASE/api/questions?lang=en" "https://son-habitos.vercel.app/disclaimer.es.html"; do
  printf '%-70s ' "$u"
  curl -sS -L --max-time 25 -o /dev/null -w 'HTTP %{http_code}\n' "$u" || echo 'NO ANSWER'
done
